import json,html
from pathlib import Path
r=Path(__file__).resolve().parents[1]; out=r/'docs/mission-control'; data=json.loads((out/'progress.json').read_text()); esc=html.escape
phases=data['phases']; tasks=[t for p in phases for t in p['tasks']]; statuses=['todo','doing','blocked','review','done','deferred']; ids=set()
for t in tasks:
 assert t['id'] not in ids and t['status'] in statuses; ids.add(t['id'])
 if t['status']=='done': assert t['evidence'], t['id']+' missing evidence'
 for e in t['evidence']:
  f=(r/e).resolve(); assert f.is_relative_to(r) and f.is_file(),e
n=sum(t['status']=='done' for t in tasks); pct=round(n/len(tasks)*100); cards=[]; evidence=[]
for p in phases:
 rows=[]; count=sum(t['status']=='done' for t in p['tasks'])
 for t in p['tasks']:
  links=[]
  for e in t['evidence']:
   link=f'<a href="../../{esc(e,quote=True)}">{esc(Path(e).name)}</a>'; links.append(link)
   evidence.append(f'<article><b>{esc(t["id"])}</b> {link}'+(f'<img loading="lazy" src="../../{esc(e,quote=True)}" alt="QA screenshot">' if Path(e).suffix.lower() in ['.png','.jpg','.jpeg','.webp'] else '')+'</article>')
  rows.append(f'<div class="task" data-status="{t["status"]}"><span class="tag {t["status"]}">{t["status"]}</span><span><small>{esc(t["id"])} · {t["priority"]}</small><br>{esc(t["title"])}<div class="note">{esc(t["note"])} {" · ".join(links)}</div></span></div>')
 cards.append(f'<details open><summary><span>SPEC-{p["id"]} · {esc(p["name"])}</span><small>{count}/{len(p["tasks"])}</small></summary><progress value="{count}" max="{len(p["tasks"])}"></progress><nav><a href="../../{p["spec"]}">Specification</a> <a href="../../{p["plan"]}">Plan</a></nav>'+''.join(rows)+'</details>')
style='''*{box-sizing:border-box}body{margin:0;background:#f5f6f0;color:#263c33;font:15px system-ui,sans-serif}main{max-width:1120px;margin:auto;padding:32px 20px}header{background:#264a3c;color:white;padding:30px;border-radius:24px}h1{font-size:36px;margin:8px 0}p{line-height:1.6}small,.note{color:#68796e;font-size:12px}header small{color:#c4d8c7}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:18px 0}.metric,details,article{background:white;border:1px solid #dbe3d9;border-radius:16px;padding:18px}.metric b{display:block;font-size:28px}progress{width:100%;height:10px;accent-color:#64956d}details{margin:12px 0}summary{cursor:pointer;font-weight:700;font-size:18px;display:flex;justify-content:space-between;gap:10px}nav{margin:12px 0;display:flex;gap:16px;flex-wrap:wrap}a{color:#356b53}button,select{font:inherit;padding:9px 14px;border:1px solid #cedbd0;border-radius:9px;background:white;color:inherit;cursor:pointer}.task{display:flex;gap:14px;align-items:start;padding:12px 0;border-top:1px solid #edf0eb}.tag{min-width:74px;text-align:center;border-radius:8px;padding:5px;background:#edf0ed;font-size:12px}.done{background:#d8edda}.blocked{background:#f8ddd5}.doing,.review{background:#f6e7bf}img{display:block;max-width:100%;max-height:360px;margin-top:12px}section{scroll-margin-top:20px}article{margin:10px 0}@media(max-width:600px){.metrics{grid-template-columns:repeat(2,1fr)}main{padding:14px}h1{font-size:28px}}'''
counts=''.join(f'<div class="metric"><small>{label}</small><b>{value}</b></div>' for label,value in [('Verified completion',str(pct)+'%'),('Done tasks',f'{n}/{len(tasks)}'),('In progress',sum(t['status'] in ['doing','review'] for t in tasks)),('Blocked',sum(t['status']=='blocked' for t in tasks))])
page=f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Noor Mission Control</title><style>{style}</style><main><header><small>WEEKEND APP CHALLENGE / v{esc(data['version'])}</small><h1>✦ Noor · Mission Control</h1><p>Tablet-first Islamic learning game · SDD roadmap and verified evidence</p></header><div class="metrics">{counts}</div><progress value="{n}" max="{len(tasks)}"></progress><nav><a href="#roadmap">Roadmap</a><a href="#evidence">Evidence gallery</a><a href="../../docs/product.md">Product</a><a href="../../docs/architecture.md">Architecture</a><a href="../../docs/decisions/000-baseline.md">Decisions</a><a href="../../docs/curriculum/README.md">Curriculum</a></nav><section id="roadmap"><h2>Roadmap</h2><label>Task status <select id="filter"><option value="all">All tasks</option>{''.join(f'<option>{s}</option>' for s in statuses)}</select></label> <button id="expand">Expand all</button> <button id="collapse">Collapse all</button>{''.join(cards)}</section><section id="evidence"><h2>QA evidence gallery</h2>{''.join(evidence) or '<article>No implementation evidence yet. Real screenshots and test reports will appear here.</article>'}</section><p><small>Generated from progress.json. Completion excludes deferred tasks from the numerator, not denominator. Edit canonical data then regenerate. No remote service required.</small></p></main><script>document.querySelector('#filter').onchange=e=>document.querySelectorAll('.task').forEach(t=>t.hidden=e.target.value!=='all'&&t.dataset.status!==e.target.value);document.querySelector('#expand').onclick=()=>document.querySelectorAll('details').forEach(d=>d.open=true);document.querySelector('#collapse').onclick=()=>document.querySelectorAll('details').forEach(d=>d.open=false);</script></html>'''
# Explicit hidden style needed because .task defines display:flex.
page=page.replace('</style>','[hidden]{display:none!important}</style>'); (out/'index.html').write_text(page)
print(f'Generated dashboard: {len(tasks)} tasks, {n} verified complete')
